/**
 * Crisis Command — Phase 2 contract layer.
 * =========================================================================
 * Phase 1's `src/crisis/types.ts` is the single source of truth for the
 * shared data contract — this file RE-EXPORTS it (never redefines it) and
 * adds only Phase-2/3 extensions:
 *
 *   Phase 2: CrisisAssignment, CrisisCoordinator, CrisisAccess,
 *            coordinator-side CrisisEvent extensions (acknowledgedBy,
 *            assignments, autoGenerated, linkedEventIds), tsToMs,
 *            isActiveEvent.
 *   Phase 3: OrgEventFilters, ResponseAnalytics, IncidentReport
 *            (imported by historyService.ts / OrgHistory.tsx).
 *
 * `CrisisEvent` here = Phase 1's CrisisEvent + optional coordinator-side
 * fields, so Phase 1 payloads remain assignable everywhere.
 */
import type {
  CrisisEvent as Phase1CrisisEvent,
  CrisisResponse as Phase1CrisisResponse,
} from './types';

export type {
  CrisisResponse,
  EmergencyContact,
  EmergencyContactsDoc,
  SituationKind as CrisisSituation,
  SOSStatus as CrisisStatus,
  SOSSeverity as CrisisSeverity,
  AckStatus as CrisisAckStatus,
  SOSLocation as CrisisLocation,
  SOSMedicalShare as CrisisMedicalShare,
  SenderSnapshot,
  TriggerSOSInput,
} from './types';
export { CRISIS_COLLECTIONS, SITUATION_SEVERITY } from './types';

/** Phase-2 write: a sevadar assigned to an incident by a coordinator. */
export interface CrisisAssignment {
  uid: string;
  name: string;
  assignedBy: string;
  assignedAt: number;
}

/**
 * CrisisEvent with Phase-2 coordinator-side fields. Every extension is
 * optional, so a raw Phase 1 document is always assignable.
 */
export interface CrisisEvent extends Phase1CrisisEvent {
  /** Coordinator who acknowledged (Phase-2 write). */
  acknowledgedBy?: string;
  acknowledgedAt?: number;
  /** Sevadar assignments (Phase-2 write). */
  assignments?: CrisisAssignment[];
  /** Crowd-density auto-escalation (crisisIntelligence). */
  autoGenerated?: boolean;
  linkedEventIds?: string[];
}

/** crisisCoordinators/{orgId}_{uid} — the Crisis Coordinator role edge. */
export interface CrisisCoordinator {
  orgId: string;
  uid: string;
  name: string;
  assignedBy: string;
  assignedAt: number;
}

/** Fail-closed RBAC ladder for the command dashboard. */
export type CrisisAccessLevel = 'trustee' | 'coordinator' | 'sevadar' | 'locked';

export interface CrisisAccess {
  level: CrisisAccessLevel;
  /** Still resolving auth / coordinator edge — show skeleton, never locked. */
  loading: boolean;
  canView: boolean;
  canAcknowledge: boolean;
  canRespond: boolean;
  canAssign: boolean;
  canEscalate: boolean;
  canBroadcast: boolean;
  canResolve: boolean;
  canManageCoordinators: boolean;
}

/* ------------------------------------------------------------------ */
/* Phase 3 (history & analytics) contract                               */
/* ------------------------------------------------------------------ */

/** Filters for the org incident history (all optional, client-side). */
export interface OrgEventFilters {
  situation?: import('./types').SituationKind | 'all';
  status?: import('./types').SOSStatus | 'all';
  fromMs?: number;
  toMs?: number;
  search?: string;
}

/** Aggregated response analytics for the org history view. */
export interface ResponseAnalytics {
  avgFirstAckSec: number | null;
  avgResolveSec: number | null;
  bySituation: Record<import('./types').SituationKind, number>;
  trend: { dayStartMs: number; count: number }[];
  sampleSizeAck: number;
  sampleSizeResolve: number;
  totalEvents: number;
}

/** Printable incident report (event + responses + timings). */
export interface IncidentReport {
  event: CrisisEvent;
  responses: Phase1CrisisResponse[];
  firstAckSec: number | null;
  resolveSec: number | null;
  generatedAt: number;
  generatedByUid: string;
  generatedByName: string;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/** Normalise epoch-ms | Firestore Timestamp | null | undefined → epoch ms. */
export function tsToMs(
  v: number | { toMillis: () => number } | null | undefined,
): number {
  if (v == null) return 0;
  if (typeof v === 'number') return v;
  try {
    return v.toMillis();
  } catch {
    return 0;
  }
}

/** "Active" = still needs coordination (not resolved/cancelled). */
export function isActiveEvent(e: { status: string }): boolean {
  return e.status === 'active' || e.status === 'acknowledged' || e.status === 'responding';
}
